    out.push(sel('country', 'Quốc Gia Phát Hành', [['Tất Cả', ''], ['Việt Nam', 'vn'], ['Trung Quốc', 'cn'], ['Nhật Bản', 'jp'], ['Hàn Quốc', 'kr'], ['Âu Mỹ', 'us'], ['Khác', 'other']]));
